import React, { useEffect, useState } from "react";
import styles from "./Browse.module.css";
import Navbar from "../component/Navbar/Navbar";
import Banner from "../component/Banner/Banner";
import MovieList from "../component/MovieList/MovieList";
import fetchMovie, { requests } from "../../fetchMovie";

function Browse() {
  const [movie, setMovie] = useState({ results: [] });
  const [banner, setBanner] = useState({});
  const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original";

  useEffect(() => {
    async function fetchMovie(requests) {
      try {
        const urlsEndpoints = [
          requests.fetchTrending,
          requests.fetchNetflixOriginals,
          requests.fetchTopRated,
          requests.fetchActionMovies,
          requests.fetchComedyMovies,
          requests.fetchHorrorMovies,
          requests.fetchRomanceMovies,
          requests.fetchDocumentaries,
          requests.fetchSearch,
        ];
        const responses = await Promise.all(
          urlsEndpoints.map((url) => fetch(`${BASE_URL}${url}`))
        );
        if (!responses.ok) {
          throw new Error("failed to fetch");
        }

        const data = await Promise.all(responses.map((res) => res.json()));
        return data;
      } catch (err) {
        console.error(err.message);
        return [];
      }
    }
    fetchMovie();
  }, []);

  // useEffect(() => {
  //   if (movie.results.length > 0) {
  //     setBanner(
  //       movie.results[Math.floor(Math.random() * movie.results.length)]
  //     );
  //     console.log(movie);
  //   }
  // }, [movie]);

  // console.log(banner);
  return (
    <div className={styles.browse}>
      <Navbar></Navbar>
      <Banner banner={banner} IMAGE_BASE_URL={IMAGE_BASE_URL}></Banner>
      <MovieList movie={movie}></MovieList>
    </div>
  );
}

export default Browse;
